        {Boolean(pendingProjects.length) && <section className="case-pending-operations" aria-label="未完成的项目创建"><h3>待核对的项目创建</h3>{pendingProjects.map(operation => <article key={operation.operationId}><strong>{operation.phase === 'project_created' ? '项目已创建，关联尚未完成' : operation.phase === 'needs_review' ? '创建结果需要核对' : '创建操作尚未确认完成'}</strong><p>{operation.projectId ? projects.find(project => project.id === operation.projectId)?.name ?? `原项目 ${operation.projectId}` : '原项目身份尚未确认'}</p><p className="case-help">{operation.phase === 'project_created' ? '原项目保留在项目空间，可核对当前 Case 后继续关联。' : '已保留原操作与可能产生的项目目录。请保留现场核对，不会自动重建或删除。'}</p><details><summary>查看操作记录</summary><p className="case-help">操作编号：{operation.operationId}<br />项目编号：{operation.projectId ?? '尚未记录'}<br />阶段：{operation.phase}<br />记录时间：{caseDate(operation.updatedAt)}</p></details>{operation.phase === 'project_created' && operation.projectId && (active ? <button type="button" className="secondary-button" onClick={() => setEditing({ kind: 'recover-project', operation, record: detail.case })}>核对并继续关联</button> : <p className="case-help">此 Case 已结束。重新打开后，可从这里继续原关联。</p>)}</article>)}</section>}
